151|export function snapshotCodeTree(rootDir) {
152|	const snapshot = { fileCount: 0, totalBytes: 0, latestMtimeMs: 0 };
153|	try {
154|		const stack = [rootDir];
155|		while (stack.length > 0) {
156|			const current = stack.pop();
157|			let entries;
158|			try {
159|				entries = fs.readdirSync(current, { withFileTypes: true });
160|			} catch {
161|				continue;
162|			}
163|			for (const entry of entries) {
