32|	// Auto-detect is the default: an empty harness config or a literal
33|	// "auto" token means the daemon probes the host on boot (PATH, the
34|	// standard install dirs, per-harness install dirs, KAINBAIN_*_BIN
35|	// overrides, and the pi agent snapshot — see detectAvailableHarnesses
36|	// in daemon.js) and fail-fasts when nothing is found. Pass --manual
37|	// --harness NAME at install time to pin.
38|	const isAutoToken = (h) => String(h ?? "").trim().toLowerCase() === "auto";
39|	let harnessAuto = false;
40|	const harnessIds = str("KAINBAIN_RUNNER_HARNESSES", "")
