134|	if (!dispatch && !projectId) {
135|		errors.push("KAINBAIN_RUNNER_PROJECT_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
136|	}
137|	if (!dispatch && !taskId) {
138|		errors.push("KAINBAIN_RUNNER_TASK_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
139|	}
