1|// Domain: Multi-project registry — engine-global adopted-project tracking.
2|// Projects that live outside every scanned root (an existing repo adopted via
3|// POST /projects/register, or an extra root added by hand) are persisted in
4|// `~/.kainbain/projects.json` (`{ roots: [...], projects: [...] }`) so the
5|// scanner re-discovers them after a restart. The file is advisory: missing,
6|// corrupt, or unreadable degrades to "no registered entries", never a broken
7|// boot. Writes are atomic (temp file + rename).
8|import fs from "node:fs";
9|import os from "node:os";
10|import path from "node:path";
11|import { config } from "./config.js";
12|
13|/***
14| * MARK: DEFAULT_REGISTRY_FILENAME
15| * @description Basename of the engine-global projects registry file.
16| * @example DEFAULT_REGISTRY_FILENAME === "projects.json"
17| ***/
18|export const DEFAULT_REGISTRY_FILENAME = "projects.json";
19|
20|/***
21| * MARK: resolveRegistryPath
22| * @description The active registry file path: the configured
23| *   `projectsRegistryFile` (`KAINBAIN_PROJECTS_REGISTRY_FILE`), defaulting
24| *   to `~/.kainbain/projects.json`.
25| * @example resolveRegistryPath() => '~/.kainbain/projects.json'
26| * @param {Object} [overrides]
27| * @param {string} [overrides.registryFile] - Explicit path (tests inject).
28| * @returns {string}
29| ***/
30|export function resolveRegistryPath(overrides = {}) {
31|	if (
32|		typeof overrides.registryFile === "string" &&
33|		overrides.registryFile.trim()
34|	) {
35|		return path.resolve(overrides.registryFile.trim());
36|	}
37|	const configured = config?.projectsRegistryFile;
38|	if (typeof configured === "string" && configured.trim()) {
39|		return path.resolve(configured.trim());
40|	}
41|	return path.join(os.homedir(), ".kainbain", DEFAULT_REGISTRY_FILENAME);
42|}
43|
44|/***
45| * MARK: normalizeRegistryData
46| * @description Normalizes raw registry content into `{ roots, projects }`
47| *   string arrays: trims, drops blanks and non-strings, dedupes. Garbage
48| *   degrades to empty lists, never throws.
49| * @example normalizeRegistryData({ roots: ['/a', '/a'], projects: [null] }) => { roots: ['/a'], projects: [] }
50| * @param {unknown} raw
51| * @returns {{roots: string[], projects: string[]}}
52| ***/
53|export function normalizeRegistryData(raw) {
54|	const clean = (value) => {
55|		if (!Array.isArray(value)) return [];
56|		const seen = new Set();
57|		const out = [];
58|		for (const entry of value) {
59|			if (typeof entry !== "string") continue;
60|			const trimmed = entry.trim();
61|			if (!trimmed || seen.has(trimmed)) continue;
62|			seen.add(trimmed);
63|			out.push(trimmed);
64|		}
65|		return out;
66|	};
67|	if (!raw || typeof raw !== "object") return { roots: [], projects: [] };
68|	return { roots: clean(raw.roots), projects: clean(raw.projects) };
69|}
