71|/***
72| * MARK: readRegistry
73| * @description Reads the registry file: `{ roots, projects }`, normalized.
74| *   A missing or corrupt file reads as empty (the scanner simply finds
75| *   nothing extra). Never throws.
76| * @example readRegistry({ registryFile: '/tmp/none.json' }) => { roots: [], projects: [] }
77| * @param {Object} [overrides]
78| * @param {string} [overrides.registryFile] - Explicit path (tests inject).
79| * @returns {{roots: string[], projects: string[]}}
80| ***/
81|export function readRegistry(overrides = {}) {
82|	const file = resolveRegistryPath(overrides);
83|	try {
84|		/* eslint-disable security/detect-non-literal-fs-filename */
85|		if (!fs.existsSync(file)) return { roots: [], projects: [] };
86|		const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
87|		return normalizeRegistryData(parsed);
88|		/* eslint-enable security/detect-non-literal-fs-filename */
89|	} catch {
90|		return { roots: [], projects: [] };
91|	}
92|}
