114|		fs.renameSync(tempPath, file);
115|		/* eslint-enable security/detect-non-literal-fs-filename */
116|		return true;
117|	} catch (err) {
118|		console.error(`[projectRegistry] failed to write ${file}:`, err);
119|		return false;
