{"content":"// Q4 negative probe: cross-project replay must be rejected.
// Uses temp state files only; never touches live roots.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "kb-q4-probe-"));
process.env.KAINBAIN_CLAIM_STATE_FILE = path.join(tmp, "claims.json");
process.env.PROJECTS_ROOT = path.join(tmp, "projects");
process.env.NOTES_SPACE_ROOT = path.join(tmp, "notes");
process.env.KAINBAIN_PROJECTS_REGISTRY_FILE = path.join(tmp, "projects.json");

const { ClaimStore } = await import("/home/[REDACTED]/.kainbain/runner-work/kb-5fdea223-6b10-460e-8ae7-388526798085/api/flow/claimStore.js");
const { ExecutionLedger } = await import("/home/[REDACTED]/.kainbain/runner-work/kb-5fdea223-6b10-460e-8ae7-388526798085/api/flow/executionLedger.js");

const claims = new ClaimStore({ stateFile: path.join(tmp, "claims.json") });
const ledger = new ExecutionLedger();

// Fake task store: task t1 lives ONLY in proj-alpha.
const tasks = { "proj-alpha": new Map([["t1", { id: "t1", status: "in_stage", currentStageId: "s1", logEntries: [] }]]) };
const taskStore = {
  getTask: (pid, tid) => tasks[pid]?.get(tid) ?? null,
  updateTask: (pid, tid, patch) => Object.assign(tasks[pid].get(tid), patch),
};

// 1. Runner claims t1 for proj-alpha.
const { executionId, epoch } = claims.claim("t1", "runner-1", "proj-alpha");
console.log("claim ok:", { epoch, holdProject: claims.describe("t1").projectId });

// 2. Correct progress succeeds.
const ok = ledger.recordProgress({ claimStore: claims, taskStore, projectId: "proj-alpha", taskId: "t1", runnerId: "runner-1", executionId, epoch, stageId: "s1", event: "start" });
console.log("correct-project progress accepted:", !!ok);

// 3. Same lease, wrong project (proj-beta): task lookup misses -> guardedTask 404s in routes;
//    ledger-level: getTask returns null. Simulate route guard:
const crossTask = taskStore.getTask("proj-beta", "t1");
console.log("cross-project task lookup (expect null -> route 404):", crossTask);

// 4. Stale epoch replay rejected.
try {
  ledger.recordProgress({ claimStore: claims, taskStore, projectId: "proj-alpha", taskId: "t1", runnerId: "runner-1", executionId, epoch: epoch + 99, stageId: "s1", event: "replay" });
  console.log("STALE EPOCH ACCEPTED -- BAD");
} catch (e) { console.log("stale epoch rejected:", e.code); }

// 5. Second runner cannot steal the lease.
try {
  claims.claim("t1", "runner-2", "proj-alpha");
  console.log("DOUBLE CLAIM ACCEPTED -- BAD");
} catch (e) { console.log("double claim rejected:", e.code); }

// 6. Ledger does NOT compare hold.projectId to request projectId (defense-in-depth gap?):
//    craft a colliding task id in proj-beta and replay the same executionId/epoch.
tasks["proj-beta"] = new Map([["t1", { id: "t1", status: "in_stage", currentStageId: "s1", logEntries: [] }]]);
try {
  ledger.recordProgress({ claimStore: claims, taskStore, projectId: "proj-beta", taskId: "t1", runnerId: "runner-1", executionId, epoch, stageId: "s1", event: "xproj" });
  console.log("COLLIDING-ID cross-project progress ACCEPTED (relies on uuid uniqueness)");
} catch (e) { console.log("colliding-id cross-project rejected:", e.code); }

fs.rmSync(tmp, { recursive: true, force: true });
console.log("probe tmp cleaned:", !fs.existsSync(tmp));
","path":"/tmp/kb-q4-probe.mjs"}

