				throw RunnerRegistry._fail(
					400,
					"INVALID_DISPLAY_NAME",
					"displayName must not be blank.",
				);
			}
			if (trimmed.length > 128) {
				throw RunnerRegistry._fail(
					400,
					"INVALID_DISPLAY_NAME",
					"displayName must be at most 128 characters.",
				);
